import z3
import itertools
opt = z3.Optimize()
e = [[z3.Bool(f"e{i}_{j}") for j in range(7)] for i in range(7)]
for i1 in range(7):
    for i2 in range(i1 + 1, 7):
        for j1 in range(7):
            for j2 in range(j1 + 1, 7):
                opt.add(z3.Or([z3.Not(e[i1][j1]), z3.Not(e[i1][j2]), z3.Not(e[i2][j1]), z3.Not(e[i2][j2])]))
for a_list in itertools.combinations(range(7), 3):
    for b_list in itertools.combinations(range(7), 3):
        for perm in itertools.permutations(range(3)):
            cycle_edges = []
            for k in range(3):
                aa = a_list[k]
                for m in range(3):
                    if m != perm[k]:
                        bb = b_list[m]
                        cycle_edges.append(e[aa][bb])
            opt.add(z3.Or([z3.Not(ee) for ee in cycle_edges]))
sum_edges = sum([z3.If(e[i][j], 1, 0) for i in range(7) for j in range(7)])
opt.maximize(sum_edges)
print(opt.check())
if opt.check() == z3.sat:
    print(opt.upper(sum_edges))
    model = opt.model()
    edges_list = []
    for i in range(7):
        for j in range(7):
            if model.evaluate(e[i][j]):
                edges_list.append((i, j+7))
    print(len(edges_list))
    print(edges_list)
else:
    print("unsat")
